from review_io import commit
c={}
def a(i,t,r='تصحيح المعنى والنحو والصياغة في الحوار المتصل.'):c[i]=(t,r)
a(1000,'<ffx:smile_light>فقد كانت تلك المدينة مشهورة بمحاربيها! <ffx:wonder>قال المعلم إن ثلاثمائة منهم تصدّوا ذات يوم لجيش هائل دفاعًا عن اليونان!<ffx:neutral>')
a(1002,'<ffx:sadness>لا، ماتوا جميعًا في النهاية... <ffx:smile>لكنهم لم يجبنوا! وما زال الجميع يذكرهم حتى اليوم! <ffx:sadness>إلا أنتم أيها الحمقى...<ffx:neutral>')
a(1003,'<ffx:smile>رائع! مثل صاحبنا سيري تمامًا!<ffx:neutral>')
a(1009,'<ffx:sadness>أرى أنه ما كان علينا معاقبته هكذا. <ffx:disgust_light>فهو لم يكذب، <ffx:disgust>بل الجوّال! <ffx:anger_light>ثم إن أوليا هي من شتتت انتباهه!<ffx:neutral>','أوليا تصغير اسم أولغا، لا عليا.')
a(1010,'<ffx:anger_light>لقد عوقب على غبائه لا على الكذب! <ffx:wonder>لا يجوز أن تكون بهذا الغباء وأنت تحرس أحدًا! <ffx:fear_light>من حسن حظه أن الجوّال اكتفى بالرحيل، فقد كان يستطيع <ffx:disgust_light>ذبح ذلك الأبله!<ffx:neutral>')
a(1014,'<ffx:wonder_light>فهو لم يؤذنا في شيء... <ffx:wonder>ثم من يحرس المعسكر إن طاردناه جميعًا؟ <ffx:fear>تخيل لو جاء سيد الغابة!<ffx:neutral>','المقصود الدب الملقب بسيد الغابة.')
a(1015,'<ffx:sadness>أظنني لم أفكر في العواقب...<ffx:neutral>')
a(1024,'<ffx:sadness>لعلهم فعلوا... <ffx:wonder>وأظن أن المدرّبين يرون ذلك أيضًا، <ffx:anger_light>فقد وضعوا حراسًا بين معسكرنا ومعسكرهم... <ffx:wonder>ثم هل سمعت كلامهم؟ <ffx:disgust>حتى كلامهم صار ككلام قطاع الطرق!<ffx:neutral>')
a(1026,'أرتيوم، أليوشا... هذه رسالة مسجلة. إن سمعتماها، فاعلما أن أورورا يتحرك نحو السد. اذهبا إليه بأسرع ما يمكن. أكرر، اذهبا إلى نقطة اللقاء بأسرع ما يمكن!')
a(1027,'<ffx:anger>لا تتحرك أيها الجوّال!<ffx:neutral>')
a(1028,'<ffx:smile>ها نحن نلتقي مجددًا! <ffx:wonder>لكن أراهن أنك لا تتذكر من أخرجك من الماء... <ffx:smile_light>اسمي أولغا، بالمناسبة.<ffx:neutral>')
a(1030,'<ffx:anger>تبًا! <ffx:sadness>عذرًا يا معلم... <ffx:disgust_light>القفل كله صدئ...<ffx:neutral>')
a(1033,'<ffx:wonder>ألا تسمعني؟! أين سرحت؟ هل تساعدني قليلًا؟<ffx:neutral>')
a(1034,'<ffx:disgust>حتى أحد القراصنة كان ليساعدني الآن! <ffx:wonder>من ربّاك هكذا؟<ffx:neutral>')
a(1037,'<ffx:sadness>آسفة لأنني لا أستطيع مرافقتك. <ffx:disgust_light>في جلسة المجلس اليوم، اقترح القراصنة مهاجمة قطاركم، <ffx:anger>مع أنه لا يحق لهم حتى عقد جلسة في غيابي.<ffx:neutral>')
a(1040,'<ffx:smile_light>لا يحبون مشاركة ما يملكون، <ffx:sadness>لكن هذا لا يبرر مهاجمتهم...<ffx:neutral>')
a(1044,'<ffx:smile_light>من هناك أخذت أنا وأليوشا قاربًا، <ffx:sadness>سامحني يا معلم... <ffx:wonder>ما زالت هناك قوارب، لكن احذر.<ffx:neutral>')
a(1045,'<ffx:wonder>حسنًا أيها الجوّال... <ffx:smile>اعتنِ بنفسك، ولا تجعلني أندم على مساعدتكم! <ffx:wide_smile_light>بلّغ أليوشا سلامي!<ffx:neutral>')
a(1047,'<ffx:smile_light>لعل هذا يهيئني لأكون صوت العقل الليلة. <ffx:disgust_light>لقد سئمت تبجحهم حقًا، همف!<ffx:neutral>')
a(1049,'<ffx:sadness>أما أنا فغارقة في أفكاري هنا...<ffx:neutral>')
a(1050,'<ffx:sadness_light>منذ أن اتخذ سيد الغابة جوار هذا المكان موطنًا له، <ffx:sadness>كاد الناس يتوقفون عن المجيء، <ffx:wonder_light>رغم أنهم لم ينسوه.<ffx:neutral>')
a(1051,'<ffx:wonder_light>ربّانا المعلم جميعًا، وعلّمنا كيف نعيش في الغابة... <ffx:sadness>لولاه لمتنا منذ زمن <sigh><ffx:sadness_light>لذلك كنا نحن الفتيات نزوره كل يوم، وما زال الشبان يأتون من حين إلى آخر...')
a(1053,'<ffx:wonder_light>خرج معظمنا في رحلة مع مجرى النهر، <ffx:sadness_light>ولم يبق في المعسكر إلا نفر قليل للحراسة. <ffx:anger_light>حين عدنا وجدنا أن قطاع الطرق قد أغاروا عليه... <ffx:sadness_strong>ما زال تذكر ذلك المشهد يؤلمني... <ffx:disgust_strong>لا أستطيع حتى وصفه...<ffx:neutral>')
a(1055,'<ffx:sadness_strong>ساعدنا المعلم في دفن قتلانا... <ffx:sadness_light>كان الظلام قد حل <ffx:fear_light>حين عاد الشبان وجلسوا حول النار... <ffx:fear_strong>كان الدم يغطي رومان حتى <ffx:disgust_strong>لم يظهر منه إلا عيناه وأسنانه. <ffx:sadness_strong>ثم بدأوا الكلام...<ffx:neutral>','تصحيح دفن الضحايا لا دفن المتحدثين الأحياء.')
a(1056,'<ffx:sadness>كان تتبعهم سهلًا؛ <ffx:disgust>فقطاع الطرق لم يحاولوا إخفاء آثارهم. <ffx:wonder_light>انتظر الشبان حتى سكروا جميعًا في معسكرهم، <ffx:anger_light>ثم رشقوهم بالسهام... <ffx:fear>وبعدها ذبح رومان الجرحى كما تُذبح الغزلان...<ffx:neutral>')
a(1058,'<ffx:sadness>وفي الصباح كان قد رحل إلى هذه الكنيسة. <ffx:sadness_light>لم يكن يكلم أحدًا في البداية، <ffx:wonder_light>لكننا نحن الفتيات واصلنا زيارته، نحمل إليه بعض التوت أو نطلب نصيحته...<ffx:neutral>')
a(1060,'<ffx:sadness>لم يعد يتحدث إلى الشبان الأكبر سنًا، لكنه كان يجيب رسائلهم. وكان يقول لنا نحن الذين واصلنا زيارته <ffx:wonder_light>إن علينا أن نكون ضميرهم... <ffx:sadness>وأن نمنعهم من التحول إلى وحوش... <ffx:wonder>لكن كيف نفعل ذلك؟<ffx:neutral>')
a(1062,'<ffx:fear_light>ذات يوم أسروا نحو عشرة من قطاع الطرق، واستخدموهم «لاختبار» جميع الفتيان... <ffx:disgust_strong>أجبروهم على قتل أولئك الأوغاد. <ffx:anger_light>لم يستطع أحد من جماعتنا فعل ذلك، فوصموهم بالجبن ونبذوهم... <ffx:sadness_light>وهكذا ظهرت جماعة «الطليعيين»...<ffx:neutral>')
a(1066,'<ffx:anger>يبدو أن ذلك هزّ رومان أخيرًا... <ffx:sadness_light>فهدأ، وانضم بعض الشبان الأكبر سنًا إلى الطليعيين... <ffx:wonder_light>فالمهم في النهاية أن نبقى معًا... لذا...<ffx:neutral>')
a(1067,'<ffx:wonder>والآن أصبح صوتي مسموعًا في المجلس. <ffx:smile>لأنني أستطيع تلقينهم درسًا إن لم يصغوا إليّ!<ffx:neutral>')
a(1071,'<ffx:sadness_light>وفي أحد اجتماعات المجلس، أقنع رومان ومدرّبونا الجميع بالتصويت ضد الأدميرال، <ffx:wonder_light>فبنى القراصنة حصنًا جديدًا قرب الضفة، حيث لا يزال البقاء آمنًا...<ffx:neutral>')
a(1072,'<ffx:anger_light>رفض الأدميرال ذلك كله، وبقي هو <ffx:disgust_light>وأشد أتباعه تعصبًا في المنشرة. <ffx:sadness_light>ولم نسمع عنهم مجددًا. لا مجال للاستهانة بالإشعاع، <ffx:sadness>فالمعلم لم يحذرنا عبثًا...<ffx:neutral>')
a(1073,'<ffx:wonder>والآن، في غياب الأدميرال، <ffx:smile_light>لا أحد يجرؤ على <ffx:anger_light>إثارة المتاعب لي في المجلس... <ffx:smile>سأضع حدًا لتصرفاتهم الليلة، فلا تقلق...<ffx:neutral>')
a(1078,'<ffx:anger>سأقول لهم رأيي فيهم بصراحة...<ffx:neutral>')
a(1083,'<ffx:wonder>انظر! واحد آخر! <ffx:smile>ألم أقل لك إنه ليس وحده!<ffx:neutral>')
a(1085,'<ffx:anger>مهلًا! أنتم <ffx:disgust>الطليعيين لديكم واحد بالفعل، <ffx:wonder>وهذا صيدنا نحن!<ffx:neutral>')
a(1087,'<ffx:anger>الشبكة لي، فاذهب إلى الجحيم!<ffx:neutral>')
a(1088,'<ffx:wonder>ولماذا نصبت الفخ على أرضنا إذن؟ <ffx:disgust>ثم إنك أخذت حقيبة ظهر أحد الدخلاء بالفعل!<ffx:neutral>')
a(1089,'<ffx:anger>غطست لإحضار الحقيبة، أما أنت فجبنت!<ffx:neutral>')
a(1092,'<ffx:fear>السهم المتفجر! هيا!<ffx:neutral>','المقصود رأس السهم المتفجر المستخدم ضد الدب.')
a(1094,'<ffx:wonder>ماذا، أصرت قاطع طريق؟! <ffx:anger>ماذا قال المعلم؟ <ffx:sadness>قال إن علينا أن نكون مختلفين! <ffx:wonder>أنسيت؟!<ffx:neutral>')
a(1095,'<ffx:disgust>ألم يملأ الغرور رأسك؟ <ffx:anger>قال المعلم أولًا إن علينا الدفاع عن أنفسنا! أما <ffx:sadness>بقية كلامه فجاء لاحقًا... أ <ffx:wonder>نسيت ما كان الدخلاء يفعلونه هنا؟ <ffx:anger>وهذا دخيل أيضًا، فلا بد أن يموت قبل أن يأتي بغيره!<ffx:neutral>')
a(1098,'<ffx:fear_strong>اهربوا! اهربوا يا رفاق!<ffx:neutral>')
